// Copies the shared rule modules into extension/lib/, and writes the
// extension's copy of the catalog.
//
// The extension reimplements nothing: lib/schedule.js, lib/problems.js and
// lib/techniques.js hold every rule, and the popup imports them directly. A
// Chrome extension has no bundler and no disk, so the one module that reads
// the catalog off disk (lib/problem-data.js) can't be copied as-is — it is
// generated here with the same data inlined, the same way vite.config.js does
// it for the browser build. The generated file is gitignored: it is your
// problems, not the program.
import { copyFileSync, mkdirSync, writeFileSync } from 'node:fs'
import path from 'node:path'
import { REPO_ROOT, resolveData } from '../lib/data-dir.js'
import { readCatalog } from '../lib/problem-data.js'

const SHARED = ['schedule.js', 'problems.js', 'techniques.js']
const outDir = path.join(REPO_ROOT, 'extension', 'lib')

mkdirSync(outDir, { recursive: true })
for (const f of SHARED) copyFileSync(path.join(REPO_ROOT, 'lib', f), path.join(outDir, f))

const data = readCatalog(REPO_ROOT)
writeFileSync(
  path.join(outDir, 'problem-data.js'),
  `// GENERATED by scripts/sync-extension.mjs — do not edit, and do not commit.\n`
  + `export const CATALOG_DATA = ${JSON.stringify(data)}\n`,
  'utf-8',
)

const n = data.problems?.length ?? 0
console.log(`extension/lib: ${SHARED.join(', ')}, problem-data.js (${n.toLocaleString()} problems from ${resolveData(REPO_ROOT).dir})`)
